mapper.select:
/* id="selectList" */
SELECT  *
FROM    LEARNING_RECORD
WHERE   MEMBER_ID = #{memberId}
ORDER BY LEARNING_DATE DESC NULLS LAST
       ,CREATED_AT DESC

/* id="selectOne" */
SELECT  *
FROM    LEARNING_RECORD
WHERE   MEMBER_ID = #{memberId}
AND     LEARNING_ID = #{learningId}

mapper.insert:
/* id="insert" */

    SELECT  LEARNING_RECORD_SEQ.NEXTVAL
    FROM    DUAL

INSERT INTO LEARNING_RECORD (
    LEARNING_ID
   ,MEMBER_ID
   ,RECORD_TYPE
   ,SUBJECT
   ,LEARNING_DATE
   ,CONTENT
   ,DIFFICULTY
   ,REFLECTION
   ,CREATED_AT
   ,UPDATED_AT
) VALUES (
    #{learningId}
   ,#{memberId}
   ,#{recordType}
   ,#{subject}
   ,#{learningDate,jdbcType=DATE}
   ,#{content,jdbcType=CLOB}
   ,#{difficulty,jdbcType=CLOB}
   ,#{reflection,jdbcType=CLOB}
   ,SYSTIMESTAMP
   ,SYSTIMESTAMP
)

mapper.update:
/* id="update" */
UPDATE  LEARNING_RECORD
SET     RECORD_TYPE   = #{recordType}
       ,SUBJECT       = #{subject}
       ,LEARNING_DATE = #{learningDate,jdbcType=DATE}
       ,CONTENT       = #{content,jdbcType=CLOB}
       ,DIFFICULTY    = #{difficulty,jdbcType=CLOB}
       ,REFLECTION    = #{reflection,jdbcType=CLOB}
       ,UPDATED_AT    = SYSTIMESTAMP
WHERE   MEMBER_ID = #{memberId}
AND     LEARNING_ID = #{learningId}

mapper.delete:
/* id="delete" */
DELETE
FROM    LEARNING_RECORD
WHERE   MEMBER_ID = #{memberId}
AND     LEARNING_ID = #{learningId}

